-- Yabanin consolidated schema baseline (squash of migrations 0001..0014).
-- Generated by applying every up-migration to a pristine pgvector/pg16
-- database and dumping the resulting state (schema + seeds). Equivalence to
-- the 14-migration chain is proven by a byte-identical pg_dump diff
-- (14-chain-from-scratch vs baseline-from-scratch, schema + data).
-- Fresh installs run ONLY this migration. Historical deployments (schema_
-- migrations past version 1) apply nothing: pkg/migrate takes MAX(version).
-- The down side drops everything the baseline creates; it is a reset, not a
-- replay of the historical down steps.
CREATE EXTENSION IF NOT EXISTS vector;

--
-- PostgreSQL database dump
--


-- Dumped from database version 16.15 (Debian 16.15-1.pgdg12+2)
-- Dumped by pg_dump version 16.15 (Debian 16.15-1.pgdg12+2)

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: vector; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;


--
-- Name: EXTENSION vector; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION vector IS 'vector data type and ivfflat and hnsw access methods';


--
-- Name: block_lineage_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_lineage_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'request_lineage is append-only (PB1.2 tamper-evidence)';
END;
$$;


--
-- Name: bump_cache_version_on_model_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_cache_version_on_model_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- When models_registry.version is bumped, update all cache entries for
    -- that model_tier to the new version, causing semantic lookups with
    -- the old version to miss (invalidating stale cached responses).
    UPDATE cache_entries
    SET model_version = NEW.version::text
    WHERE model_tier = NEW.model_name AND model_version = OLD.version::text;
    RETURN NEW;
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;


